/*
This file contains dictionaries and other data required for the lithology
selection to work.  It includes base dictionaries, a linking table
between projects and lithologies and views and triggers to bring things
together.

See issues #44 and #87 for context.
*/
BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS "_dic_rock_all" (
	"fid"	INTEGER NOT NULL,
	"code"	TEXT NOT NULL UNIQUE,
	"description"	TEXT,
	"translation"	TEXT,
	"status"	TEXT,
	"rcs_status"  TEXT,
	"user_entered"	TEXT NOT NULL,
	"date_entered"	DATETIME NOT NULL,
	"user_updated"	TEXT,
	"date_updated"	DATETIME,
	PRIMARY KEY("fid" AUTOINCREMENT)
);

CREATE TABLE IF NOT EXISTS "dic_rock_field" (
	"fid"	INTEGER NOT NULL,
	"category"	TEXT,
	"code"	TEXT NOT NULL UNIQUE,
	"is_default"	BOOLEAN NOT NULL DEFAULT 0,
	"simple_lithology"	TEXT,
	"label" TEXT,
	"description"	TEXT,
	"translation"	TEXT,
	"composite"	TEXT,
	"user_entered"	TEXT NOT NULL,
	"date_entered"	DATETIME NOT NULL,
	"user_updated"	TEXT,
	"date_updated"	DATETIME,
	FOREIGN KEY("code") REFERENCES "_dic_rock_all"("code"),
	PRIMARY KEY("fid" AUTOINCREMENT)
);

values('dic_rock_field','attributes','dic_rock_field','Supplementary rock data for aiding field selection','2023-09-15t13:21:52.679z',null,null,null,null,null);

